"""Publish observed results without fitting or selecting new trading rules."""
from pathlib import Path
import json,html,hashlib
from datetime import datetime,timezone
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2]
def fmt(x,d=3):return {'-Infinity':'−∞','Infinity':'+∞'}.get(x,'undefined') if isinstance(x,str) else ('undefined' if x is None else f'{x:+.{d}f}')
def pct(x):return fmt(x)+'%'
def main():
    run=Path(json.loads((HERE/'run.json').read_text())['run_dir']);manifest=json.loads((run/'manifest.json').read_text());budget=json.loads((HERE/'snapshot_budget.json').read_text())
    stages={s:json.loads((run/s/'summary.json').read_text()) for s in ['screen','confirmation'] if (run/s/'summary.json').exists()}
    assert stages
    rows=[];plotrows=[];data=[]
    for stage,summary in stages.items():
        for direction,r in summary['directions'].items():
            side='Short quiet rally' if direction=='up' else 'Long quiet decline';a=r['aligned'];ci=r['primary_aligned_mean_interval']['ordinary95_finite_draw_interval']
            rows.append([stage,side,a['n'],(f"{100*a.get('win_rate',0):.1f}%" if a.get('win_rate') is not None else '—'),pct(a['mean_gross_pct']),pct(r['price_only']['mean_gross_pct']),pct(r['MA20_control'].get('mean_gross_pct')),fmt(r['fixed_effects']['adjusted_aligned_minus_opposed_pct'])+' pp',r['claim_status']])
            plotrows.append((stage,side,r))
        z=np.load(run/stage/'paths.npz');paths={int(case):p for case,p in zip(z['case'],z['paths'])}
        for line in (run/stage/'trade_ledger.jsonl').read_text().splitlines():
            r=json.loads(line);p=paths[r['case']];r['normalized_close']=([100.]+(100*p[:,3]/p[0,0]).round(5).tolist()) if r['valid_coverage'] else []
            r['normalized_high']=(100*p[:,1]/p[0,0]).round(5).tolist() if r['valid_coverage'] else [];r['normalized_low']=(100*p[:,2]/p[0,0]).round(5).tolist() if r['valid_coverage'] else []
            c=manifest['cases'][r['case']-1];r['gate_move_pct']=c['gate_move_pct'];r['volume_ratio']=c['volume_ratio'];r['input_chart']=str(Path(c['chart_file']).relative_to('data'))
            data.append(r)
    fig,axes=plt.subplots(len(plotrows),1,figsize=(10,3.2*len(plotrows)),squeeze=False,constrained_layout=True)
    for ax,(stage,side,r) in zip(axes[:,0],plotrows):
        vals=[r['aligned']['mean_gross_pct'],r['price_only']['mean_gross_pct'],r['MA20_control'].get('mean_gross_pct')];cols=['#245c91','#738694','#b79445']
        ax.barh(['AI filter','Price / volume only','MA20 filter'],[x if x is not None else np.nan for x in vals],color=cols,height=.55)
        ci=r['primary_aligned_mean_interval']['ordinary95_finite_draw_interval']
        if vals[0] is not None and all(isinstance(v,(int,float)) for v in ci):
            ax.errorbar(vals[0],0,xerr=np.array([[max(0,vals[0]-ci[0])],[max(0,ci[1]-vals[0])]]),fmt='o',color='#153348',capsize=4,markersize=4,zorder=3)
        ax.axvline(0,color='#111',lw=.8);ax.invert_yaxis();ax.grid(axis='x',alpha=.16);ax.set_axisbelow(True)
        ax.set_title(stage.capitalize()+' · '+side+f" · {r['aligned']['n']} AI-selected trades",loc='left',fontsize=12,fontweight='bold')
        ax.set_xlabel('Gross mean per trade (%) · AI whisker: ordinary 95% quarter interval')
        for i,v in enumerate(vals):
            if v is not None:ax.annotate(f'{v:+.3f}%',(v,i),xytext=(5 if v>=0 else -5,13 if i==0 else 0),textcoords='offset points',ha='left' if v>=0 else 'right',va='bottom' if i==0 else 'center')
        ax.margins(x=.25);ax.spines[['top','right','left']].set_visible(False)
    fig.savefig(HERE/'results.png',dpi=160);plt.close(fig)
    attempts=len(budget['reserved_attempts']);valid=len(data);remaining=200-attempts
    continuation=json.loads((run/'screen/continuation.json').read_text())
    confirmed=[('short' if d=='up' else 'long') for d,r in stages.get('confirmation',{}).get('directions',{}).items() if r['confirmed']]
    headline=('Historical conditional criteria passed: '+', '.join(confirmed)+'.') if confirmed else ('No strategy passed the frozen confirmation standard.' if 'confirmation' in stages else ('Short setup passed screening; confirmation pending.' if continuation['passing_directions']==['up'] else ('Screening passed; confirmation pending.' if continuation['passing_directions'] else 'Neither setup passed screening.')))
    md=['# AI decision timing: fresh historical test','',headline,'',f'Used **{attempts} of 200 new trade snapshot attempts**, yielding {valid} audited opinions. **{remaining} new credits remain**. The previous 29 unused credits and all older findings are preserved. All reported returns are gross, without fees, funding or leverage.','',
        'The hypotheses follow an earlier AI decision after a 30-minute low-volume countermove. The actual entry is after that observation; positions close 120 minutes later. No exit threshold, holding period, confidence cutoff or model was optimized on these results.','',
        '| Stage | Rule | AI trades | Win rate | AI mean | Price-only mean | MA20-only mean | Adjusted AI spread |','|---|---|---:|---:|---:|---:|---:|---:|']
    for row in rows:md.append('| '+' | '.join(map(str,row[:-1]))+' |')
    md+=['','Price-only and MA20 figures use the same eligible gates and entry/exit clock but can execute different numbers of trades. The adjusted spread compares AI-aligned versus AI-opposed gate returns within asset × original MA20-side strata. It is a difference in percentage points, not an additional portfolio return. Full opportunity averages, with skipped trades zero, are in the stage summaries.','', '## Screening and confirmation','',f"Screen decision: `{continuation['decision']}`. Passing directions: {', '.join(continuation['passing_directions']) or 'none'} (up means the short hypothesis; down means the long hypothesis). The screen is exploratory and never contributes to confirmation intervals."]
    for stage,side,r in plotrows:
        a=r['aligned'];fe=r['fixed_effects'];mi=r['primary_aligned_mean_interval'];fi=r['primary_adjusted_spread_interval'];h=r['chronological_halves'];tail=r['remove_largest_winning_events']
        md += ['',f'### {stage.capitalize()}: {side}','',f"{a['n']} trades; mean {pct(a['mean_gross_pct'])}, median {pct(a.get('median_gross_pct'))}, win rate {100*a.get('win_rate',0):.1f}%. Mean winner {pct(a.get('mean_winner_pct'))}; mean loser {pct(a.get('mean_loser_pct'))}; worst trade {pct(a.get('worst_pct'))}.",f"Ordinary 95% gross-mean interval (finite draws): [{pct(mi['ordinary95_finite_draw_interval'][0])}, {pct(mi['ordinary95_finite_draw_interval'][1])}]. Family-adjusted one-sided lower bound: {pct(mi['simultaneous98_75_one_sided_lower'])}.",f"Adjusted AI spread: {fmt(fe['adjusted_aligned_minus_opposed_pct'])} percentage points; family-adjusted lower bound {fmt(fi['simultaneous98_75_one_sided_lower'])}. Undefined bootstrap fraction: gross {mi['undefined_fraction']:.3%}, adjusted spread {fi['undefined_fraction']:.3%}; undefined draws count as −∞ for the decision lower bound. Identifying mixed strata contain {fe['mixed_aligned_n']} aligned and {fe['mixed_opposed_n']} opposed calls.",f"Chronological halves: {pct(h[0].get('mean_gross_pct'))}, {pct(h[1].get('mean_gross_pct'))}. Mean after removing the three best winning events: {pct(tail['3'].get('mean_gross_pct'))}.",f"Status: **{r['claim_status'].replace('_',' ')}**."]
    md += ['', '## What the test can establish','',
        'This is a conditionally sampled historical study, balanced across four assets and available years. It tests the selected quiet-move population; it does not estimate natural trade frequency or a compounded account return. These are fresh query windows and previously unscored target intervals, not a prospective live-market test or entirely unseen price data. Screen and confirmation periods share market quarters, so they are separate targets rather than independent market regimes.',
        'The 300 potential targets avoid the enumerated earlier scored intervals. The half-open convention permits endpoint adjacency: 230 exclusion comparisons touch an old boundary. Input histories can overlap earlier observations. Neither sampling nor model inputs use the post-entry payoff. Quarter bootstrap intervals are approximate and retain a four-statistic correction even when one direction proceeds.',
        'A reliably positive adjusted spread would support additional selection value beyond the specific asset/MA20 controls used here. It would not prove incremental value beyond all price features or that AI simulates losing retail traders.',
        '', '## Reproduction and records','',f'- Run: `{run.relative_to(ROOT)}`.', '- Frozen rules: [VALIDATION_PROTOCOL.md](VALIDATION_PROTOCOL.md).', '- Durable state: [PROJECT_MEMORY.md](PROJECT_MEMORY.md), [HANDOFF.md](HANDOFF.md), [RESEARCH_LOG.jsonl](RESEARCH_LOG.jsonl).', '- Budget: [snapshot_budget.json](snapshot_budget.json).', '- Complete interactive positions: [index.html](index.html).', '- Sampler, isolation and economic replay checks are retained in `design/` and `audit/`.']
    if 'confirmation' in stages:
        r=stages['confirmation']['directions']['up'];a=r['aligned'];h=r['chronological_halves'];best1=r['remove_largest_winning_events']['1']['mean_gross_pct']
        conclusion=f"The short setup's screening mean did not persist: confirmation averaged {pct(a['mean_gross_pct'])} across {a['n']} trades, versus {pct(r['MA20_control']['mean_gross_pct'])} for the MA20-only control. Removing only the largest winner changes the AI mean to {pct(best1)}. Its chronological halves are {pct(h[0]['mean_gross_pct'])} and {pct(h[1]['mean_gross_pct'])}. The positive point mean is too fragile to call a verified strategy."
        md[4:4]=[conclusion,'']
        conf=[x for x in data if x['stage']=='confirmation'];agree=sum((x['AI_action']=='long')==x['above_equal_MA20'] for x in conf)
        winners=[x['AI_confidence'] for x in conf if x['AI_aligned'] and x['gate_gross_pct']>0];losers=[x['AI_confidence'] for x in conf if x['AI_aligned'] and x['gate_gross_pct']<0]
        md += ['', '## What the AI decisions showed','',f"AI direction agreed with MA20 direction in {agree}/{len(conf)} confirmation cases ({100*agree/len(conf):.1f}%). Mean original confidence was {np.mean(winners):.4f} on winning selected trades and {np.mean(losers):.4f} on losing selected trades. This is a descriptive comparison, not a calibration test: the AI confidence concerned its original bracket, while this research changed the entry and exit.",'', '[AI wording, price paths and three mechanically selected examples](interpretation/AI_BEHAVIOR.md). The first 30-minute countermove is a sampling condition and cannot itself establish that the AI was wrong.', '', '[Post-score comparison at identical trade coverage](interpretation/IDENTICAL_COVERAGE.md). This separate diagnostic does not change the frozen confirmation result.']
    (HERE/'RESULTS.md').write_text('\n'.join(md)+'\n')
    table='<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in ['Stage','Rule','AI trades','Win rate','AI mean','Price only','MA20 only','Adjusted spread','Status'])+'</tr></thead><tbody>'
    table+=''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
    cards=f'<div class="cards"><div><b>{attempts} / 200</b>New attempts</div><div><b>{valid}</b>Audited opinions</div><div><b>{remaining}</b>New credits left</div><div><b>29</b>Old credits preserved</div></div>'
    intro=f'<h1>Does AI improve a delayed entry?</h1><p class="lead">{html.escape(headline)}</p><p>Quiet countermove · 30-minute observation · 120-minute hold · four assets · gross returns</p>{cards}<h2>Frozen rules, separate stages</h2>{table}<p class="note">Conditional means use different trade counts. Adjusted spread is measured in percentage points within asset × MA20 strata. Screening results do not verify a strategy.</p><img class="results" src="results.png" alt="Policy conditional gross returns by stage and direction"><p><a href="RESULTS.md">Full findings and uncertainty</a> · <a href="VALIDATION_PROTOCOL.md">Frozen protocol</a> · <a href="snapshot_budget.json">Budget ledger</a> · <a href="interpretation/AI_BEHAVIOR.md">AI behavior and examples</a> · <a href="interpretation/IDENTICAL_COVERAGE.md">Identical-coverage diagnostic</a></p>'
    if 'confirmation' in stages:intro=intro.replace('</p><p>Quiet countermove','</p><p class="note">'+html.escape(conclusion)+'</p><p>Quiet countermove')
    css='''body{font:15px system-ui;background:#f4f5f7;color:#182530;margin:0}main{max-width:1280px;margin:auto;padding:38px 28px}h1{font-size:34px;letter-spacing:-1px;margin-bottom:8px}h2{margin-top:35px}.lead{font-size:20px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:28px 0}.cards div{background:white;border:1px solid #dae0e6;border-radius:12px;padding:20px}.cards b{display:block;font-size:26px;margin-bottom:5px}table{width:100%;border-collapse:collapse;background:white;font-size:13px}th,td{text-align:left;padding:11px;border-bottom:1px solid #e3e7eb}th{background:#e8eef4}a{color:#215c91}.note{color:#52636e;max-width:1000px;line-height:1.6}.results{max-width:900px;width:100%;display:block;background:white;margin:24px 0;border:1px solid #dae0e6}select{font:inherit;padding:9px;margin-right:8px}#tradeinfo{background:white;padding:20px;line-height:1.6;border:1px solid #dae0e6}canvas{width:100%;height:340px;background:white;display:block}#positions{overflow:auto;max-height:460px}#positions tr:hover{background:#edf3fa;cursor:pointer}.positive{color:#177047}.negative{color:#ab3540}footer{line-height:1.6;margin-top:25px;color:#53626e}@media(max-width:700px){.cards{grid-template-columns:repeat(2,1fr)}main{padding:20px 12px}table{font-size:11px}}'''
    controls='<h2>Inspect every position and AI decision</h2><p>Skipped AI cases show the price-only control trade. They are not executed by the AI-filtered policy.</p><select id="stage"><option value="all">All stages</option><option>screen</option><option>confirmation</option></select><select id="alignment"><option value="all">All calls</option><option value="yes">AI selected</option><option value="no">AI skipped / control</option></select><select id="trade"></select><canvas id="path" width="1200" height="340"></canvas><div id="tradeinfo"></div><div id="positions"></div>'
    js=r'''
const DATA=__DATA__;const $=x=>document.getElementById(x);const number=x=>typeof x==='number'?(x>=0?'+':'')+x.toFixed(3):'—';let selected=[];
function filter(){selected=DATA.filter(x=>($('stage').value==='all'||x.stage===$('stage').value)&&($('alignment').value==='all'||x.AI_aligned===($('alignment').value==='yes')));$('trade').replaceChildren();selected.forEach(x=>{let o=document.createElement('option');o.value=x.case;o.textContent=`#${x.case} · ${x.stage} · ${x.asset} · ${x.AI_aligned?'selected':'skipped'} · ${number(x.gate_gross_pct)}%`;$('trade').append(o)});renderTable();draw();}
function renderTable(){let t=document.createElement('table');let h=t.createTHead().insertRow();['Case','Stage','Entry UTC','Asset','AI','Policy','Control return','MFE','MAE'].forEach(s=>{let c=document.createElement('th');c.textContent=s;h.append(c)});let b=t.createTBody();selected.forEach(x=>{let r=b.insertRow();[x.case,x.stage,x.entry_time,x.asset,x.AI_action,x.AI_aligned?'TAKE':'SKIP',number(x.gate_gross_pct)+'%',number(x.mfe_pct)+'%',number(x.mae_pct)+'%'].forEach(v=>{r.insertCell().textContent=v});r.onclick=()=>{$('trade').value=x.case;draw()}});$('positions').replaceChildren(t);}
function draw(){let x=selected.find(x=>x.case==+$('trade').value),c=$('path'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);if(!x){$('tradeinfo').textContent='No matching cases.';return}if(!x.valid_coverage){$('tradeinfo').textContent='Excluded for '+x.exclusion;return}let y=x.normalized_close,lo=Math.min(...x.normalized_low,100),hi=Math.max(...x.normalized_high,100),pad=Math.max((hi-lo)*.15,.01);lo-=pad;hi+=pad;let X=t=>55+t/120*(c.width-85),Y=v=>c.height-35-(v-lo)/(hi-lo)*(c.height-65);ctx.font='13px system-ui';ctx.strokeStyle='#e3e8ed';ctx.fillStyle='#607080';for(let i=0;i<=4;i++){let v=lo+(hi-lo)*i/4;ctx.beginPath();ctx.moveTo(55,Y(v));ctx.lineTo(c.width-30,Y(v));ctx.stroke();ctx.fillText(v.toFixed(2),3,Y(v)+4)}ctx.fillStyle='#426c9622';ctx.beginPath();x.normalized_high.forEach((v,i)=>i?ctx.lineTo(X(i+1),Y(v)):ctx.moveTo(X(1),Y(v)));for(let i=119;i>=0;i--)ctx.lineTo(X(i+1),Y(x.normalized_low[i]));ctx.closePath();ctx.fill();ctx.setLineDash([5,5]);ctx.strokeStyle='#818d97';ctx.beginPath();ctx.moveTo(X(0),Y(100));ctx.lineTo(X(120),Y(100));ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=x.gate_gross_pct>=0?'#1b7a50':'#b44049';ctx.lineWidth=2;ctx.beginPath();y.forEach((v,i)=>i?ctx.lineTo(X(i),Y(v)):ctx.moveTo(X(i),Y(v)));ctx.stroke();ctx.lineWidth=1;ctx.fillStyle='#263d50';ctx.fillText('Entry = 100 · underlying price; shaded range = minute high/low',55,20);[0,30,60,90,120].forEach(t=>ctx.fillText(t+' min',X(t)-15,c.height-8));let p=document.createElement('p');p.textContent=`Case ${x.case} · ${x.stage} · ${x.asset} · ${x.AI_aligned?'Policy takes':'Policy skips'} ${x.trade_side===1?'LONG':'SHORT'} · Gross control return ${number(x.gate_gross_pct)}%. Entry ${x.entry_time} UTC at ${x.entry_price}; exit ${x.horizon_end} UTC at ${x.exit_price}.`;let q=document.createElement('p');q.textContent=`AI: ${x.AI_action.toUpperCase()}, confidence ${x.AI_confidence}. Reason: “${x.AI_reason}”`;let r=document.createElement('p');r.textContent=`Pre-entry move ${number(x.gate_move_pct)}%; volume ratio ${x.volume_ratio.toFixed(3)}. MFE ${number(x.mfe_pct)}%; MAE ${number(x.mae_pct)}%. Original AI bracket distances are retained in the ledger but do not set this policy’s exits.`;let link=document.createElement('a');link.href='../../'+x.input_chart;link.textContent='Original anonymized chart supplied to the AI';link.target='_blank';$('tradeinfo').replaceChildren(p,q,r,link);}
$('stage').onchange=filter;$('alignment').onchange=filter;$('trade').onchange=draw;filter();
'''.replace('__DATA__',json.dumps(data,allow_nan=False).replace('</',r'<\/'))
    footer='<footer>Historical conditional study. These are unscored target intervals selected from an existing archive, not prospective live validation or wholly unseen prices. Quarter uncertainty is approximate. No real orders. Fees, funding and leverage excluded. Each AI received anonymized t0 inputs only; later observations selected the delayed trade.</footer>'
    page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI timing study · 200-credit phase</title><style>'+css+'</style><main>'+intro+controls+footer+'</main><script>'+js+'</script></html>'
    (HERE/'index.html').write_text(page)
    report={'published_at':datetime.now(timezone.utc).isoformat(),'stages':list(stages),'attempts':attempts,'valid_decisions':valid,'new_remaining':remaining,'old_remaining':29,'confirmed_directions':confirmed,'embedded_trade_cases':[x['case'] for x in data],'report_sha256':hashlib.sha256(page.encode()).hexdigest()}
    (HERE/'publication.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
if __name__=='__main__':main()
